		Filter outer = nestedEntityFilters(values, "urn:entity:1", "urn:entity:2");
		Filter originalInner = (Filter) outer.getArg();
		originalInner.setResultSizeEstimate(11.0d);
		originalInner.setCostEstimate(12.0d);
		originalInner.setLongMetricPlanned("innerMetric", 13L);
		outer.setResultSizeEstimate(101.0d);
		outer.setCostEstimate(102.0d);
