	@Test
	void publishesSelectiveAntiProbeInsideSelectedFiniteFilterRewrite() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern type = new StatementPattern(Var.of("entity"),
				Var.of("typePredicate", values.createIRI("urn:type")),
				Var.of("typeValue", values.createIRI("urn:Entity")));
		StatementPattern code = new StatementPattern(Var.of("entity"),
				Var.of("codePredicate", values.createIRI("urn:code")), Var.of("code"));
		Filter finiteCode = new Filter(code,
				new Or(
						new Compare(Var.of("code"), new ValueConstant(values.createLiteral("A")),
								Compare.CompareOp.EQ),
						new Compare(Var.of("code"), new ValueConstant(values.createLiteral("B")),
								Compare.CompareOp.EQ)));
		Filter source = new Filter(new Join(finiteCode, type), new Not(new Exists(probe(values, "entity"))));

		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(),
				finiteRewriteAntiJoinCosts());

		Join selected = assertInstanceOf(Join.class, result.selectedPlan(), result.selectedPlan()::toString);
		Filter antiPrefix = selected.getLeftArg() instanceof Filter
				? (Filter) selected.getLeftArg()
				: assertInstanceOf(Filter.class, selected.getRightArg(), result.selectedPlan()::toString);
		assertInstanceOf(Not.class, antiPrefix.getCondition(), result.selectedPlan()::toString);
		assertTrue(containsJoinFactor(antiPrefix.getArg(), BindingSetAssignment.class),
				"The selected finite rewrite must remain inside the anti-filter prefix: " + result.selectedPlan());
		assertTrue(containsPredicate(antiPrefix.getArg(), "urn:code"),
				"The finite code lookup must provide the anti-filter binding: " + result.selectedPlan());
		assertFalse(containsPredicate(antiPrefix.getArg(), "urn:type"),
				"The broad type guard must remain after the selective anti-filter: " + result.selectedPlan());
	}

