	private static Filter safeFilteredProbe(SimpleValueFactory values, String subjectName) {
		return new Filter(probe(values, subjectName),
				new Compare(Var.of("dose"), new ValueConstant(values.createLiteral("x")), Compare.CompareOp.NE));
	}

	private static Filter nestedEntityFilters(SimpleValueFactory values, String innerValue, String outerValue) {
		Filter inner = new Filter(assuredEntities(values),
				new Compare(Var.of("entity"), new ValueConstant(values.createIRI(innerValue)), Compare.CompareOp.NE));
		return new Filter(inner,
				new Compare(Var.of("entity"), new ValueConstant(values.createIRI(outerValue)), Compare.CompareOp.NE));
	}

	private static int commutedRoot(PackedQuery query) {
		int originalRootId = query.rootRelId();
		if (query.relOperator(originalRootId) != PackedRelOp.FILTER) {
			return 0;
		}
		int originalInnerId = query.relChild(originalRootId, 0);
		if (query.relOperator(originalInnerId) != PackedRelOp.FILTER) {
			return 0;
		}
		int rootGroupId = query.relGroup(originalRootId);
		int outerConditionId = query.relPayload(originalRootId);
		int innerConditionId = query.relPayload(originalInnerId);
		int commonBaseGroupId = query.relGroup(query.relChild(originalInnerId, 0));
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (relationId == originalRootId || query.relGroup(relationId) != rootGroupId
					|| query.relOperator(relationId) != PackedRelOp.FILTER
					|| query.relPayload(relationId) != innerConditionId) {
				continue;
			}
			int helperId = query.relChild(relationId, 0);
			if (query.relOperator(helperId) == PackedRelOp.FILTER
					&& query.relPayload(helperId) == outerConditionId
					&& query.relGroup(query.relChild(helperId, 0)) == commonBaseGroupId) {
				return relationId;
			}
		}
		return 0;
	}

	private static int derivedCorrelatedMinusFilter(PackedQuery query) {
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (query.relOperator(relationId) == PackedRelOp.FILTER
					&& (query.relRuleMask(relationId) & PackedRuleProofs.MINUS_CORRELATED_NOT_EXISTS) != 0L
					&& query.scalarOperator(query.relPayload(relationId)) == PackedScalarOp.NOT) {
				return relationId;
			}
		}
		return 0;
	}

	private static int typedSemiAntiAlternativeCount(PackedQuery query) {
		int rootGroupId = query.relGroup(query.rootRelId());
		int alternatives = 0;
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (query.relGroup(relationId) == rootGroupId
					&& (query.relOperator(relationId) == PackedRelOp.SEMI_JOIN
							|| query.relOperator(relationId) == PackedRelOp.ANTI_JOIN)) {
				alternatives++;
			}
		}
		return alternatives;
	}

